const raw = $input.first()?.json || {};
const payload = raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query) ? raw.query : raw;

const toolName = String(payload.tool_name || payload.tool || 'consultar_situacao_e_cronograma_setorial').trim();
const userId = payload.user_id ? String(payload.user_id).trim() : null;

let sectorSlugs = [];
if (Array.isArray(payload.sector_slugs)) {
  sectorSlugs = payload.sector_slugs.map((s) => String(s).trim().toLowerCase()).filter(Boolean);
} else if (typeof payload.sector_slugs === 'string' && payload.sector_slugs.trim() !== '') {
  sectorSlugs = payload.sector_slugs
    .replace(/^\{|\}$/g, '')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

const pgSectorArrayLiteral = `{${sectorSlugs.map((s) => `"${s.replace(/"/g, '')}"`).join(',')}}`;
const action = String(payload.action || 'add').trim().toLowerCase();
const businessContext = payload.business_context ? String(payload.business_context).trim() : null;
const searchQuery = String(payload.query || payload.search_query || 'Reforma Tributária LC 214 CBS IBS').trim();

return [
  {
    json: {
      tool_name: toolName,
      user_id: userId,
      sector_slugs: sectorSlugs,
      pg_sector_array: pgSectorArrayLiteral,
      action,
      business_context: businessContext,
      query: searchQuery
    }
  }
];

const item = $input.first().json;
const apiKey = ($env.GEMINI_API_KEY || '').trim();
const embeddingModel = ($env.GEMINI_EMBEDDING_MODEL || 'text-embedding-004').trim();
let vectorLiteral = null;
let embeddingSource = 'fallback_null_offline';

if (apiKey && apiKey !== 'your_gemini_api_key_here') {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${embeddingModel}:embedContent?key=${apiKey}`,
      headers: {
        'Content-Type': 'application/json'
      },
      body: {
        model: `models/${embeddingModel}`,
        content: {
          parts: [{ text: item.query || 'Reforma Tributária LC 214/2025' }]
        },
        outputDimensionality: 768
      },
      json: true,
      timeout: 7000
    });

    const values = response?.embedding?.values;
    if (Array.isArray(values) && values.length === 768) {
      vectorLiteral = `[${values.map((v) => Number(v).toFixed(6)).join(',')}]`;
      embeddingSource = embeddingModel;
    }
  } catch (err) {
    vectorLiteral = null;
    embeddingSource = `fallback_null_on_error: ${err.message}`;
  }
}

return [
  {
    json: {
      ...item,
      query_embedding_vector: vectorLiteral,
      embedding_source: embeddingSource
    }
  }
];

const rawInput = $input.first()?.json || {};
const html = typeof rawInput.data === 'string' ? rawInput.data : (typeof rawInput.body === 'string' ? rawInput.body : '');
const hasError = Boolean(rawInput.error || !html || html.length < 100);

const acts = [];
if (!hasError) {
  const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
  let match;
  while ((match = rowRegex.exec(html)) !== null && acts.length < 5) {
    const rowHtml = match[1];
    const textClean = rowHtml
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (/(Instrução Normativa|Portaria|Ato Declaratório|Solução de Consulta|Lei Complementar)/i.test(textClean)) {
      const linkMatch = rowHtml.match(/href=["']([^"']+)["']/i);
      const relativeOrAbsUrl = linkMatch ? linkMatch[1] : 'https://normas.receita.fazenda.gov.br/sijut2consulta/consulta.action';
      const officialUrl = relativeOrAbsUrl.startsWith('http')
        ? relativeOrAbsUrl
        : `https://normas.receita.fazenda.gov.br/sijut2consulta/${relativeOrAbsUrl.replace(/^\/+/, '')}`;

      acts.push({
        title: textClean.slice(0, 280),
        official_url: officialUrl,
        checked_at: new Date().toISOString(),
        source: 'SIJUT2 / Normas Receita Federal / DOU'
      });
    }
  }
}

if (acts.length === 0) {
  return [
    {
      json: {
        live_portal_status: hasError ? 'indisponivel_ou_timeout_8s' : 'sem_novos_atos_no_html',
        fallback_message: 'O portal ao vivo de Normas da Receita Federal / DOU apresentou instabilidade ou não retornou novos atos na janela de 8 segundos. Utilize os atos oficiais consolidados na base Fiscália (Tool C / RAG) e o link oficial abaixo para verificação complementar.',
        official_consultation_url: 'https://normas.receita.fazenda.gov.br/sijut2consulta/consulta.action',
        dou_section1_url: 'https://www.in.gov.br/leiturajornal',
        acts_extracted: []
      }
    }
  ];
}

return [
  {
    json: {
      live_portal_status: 'online',
      checked_at: new Date().toISOString(),
      acts_count: acts.length,
      acts_extracted: acts
    }
  }
];

const items = $input.all().map((i) => i.json);
const req = $('Normalizar Payload da Tool').first()?.json || {};

return [
  {
    json: {
      success: true,
      tool_name: req.tool_name || 'unknown',
      user_id: req.user_id || null,
      sector_slugs: req.sector_slugs || [],
      executed_at: new Date().toISOString(),
      results: items,
      response: JSON.stringify({
        tool_name: req.tool_name,
        sector_slugs: req.sector_slugs,
        results: items
      })
    }
  }
];
